export const GROUND_PLAN_CITIES: GroundPlanCity[] = JSON.parse("[{\"country\":\"GB\",\"city\":\"London\",\"cuts\":[{\"slug\":\"london-westminster\",\"signature\":true},{\"slug\":\"london-isle-of-dogs\",\"signature\":true},{\"slug\":\"london-chelsea\",\"signature\":false}],\"lesson\":\"The Thames curves where London could not build, and the embankment answers it: one continuous road hugging the bank, everything else meeting it obliquely.\"},{\"country\":\"US\",\"city\":\"New York\",\"aliases\":[\"New York City\",\"NYC\",\"Manhattan\"],\"cuts\":[{\"slug\":\"new-york-battery\",\"signature\":true},{\"slug\":\"new-york-midtown\",\"signature\":false}],\"lesson\":\"The 1811 Commissioners' Plan ruled a grid over farmland and the old Dutch lanes below Wall Street survived underneath it — which is why downtown bends and everything above it does not.\"},{\"country\":\"FR\",\"city\":\"Paris\",\"cuts\":[{\"slug\":\"paris-ile-de-la-cite\",\"signature\":true},{\"slug\":\"paris-etoile\",\"signature\":true},{\"slug\":\"paris-belleville\",\"signature\":false}],\"lesson\":\"Haussmann cut boulevards straight through the medieval city from 1853, which is why Paris radiates: the star junctions are new, the fabric between them is old.\"},{\"country\":\"ES\",\"city\":\"Barcelona\",\"cuts\":[{\"slug\":\"barcelona-eixample\",\"signature\":true},{\"slug\":\"barcelona-gothic\",\"signature\":false}],\"lesson\":\"Eixample, 1859: Cerdà chamfered every corner so trams could turn, giving Barcelona a grid of octagons no other city has.\"},{\"country\":\"MA\",\"city\":\"Fez\",\"aliases\":[\"Fes\"],\"cuts\":[{\"slug\":\"fez-medina\",\"signature\":true},{\"slug\":\"fez-ville-nouvelle\",\"signature\":false}],\"lesson\":\"Fes el-Bali grew without wheeled traffic, so its lanes answer only to footfall and property lines — the densest car-free fabric on earth.\"},{\"country\":\"IT\",\"city\":\"Turin\",\"aliases\":[\"Torino\"],\"cuts\":[{\"slug\":\"turin-centro\",\"signature\":true}],\"lesson\":\"Augusta Taurinorum was a Roman camp, and the grid inside the old walls is still its cardo and decumanus, two thousand years on.\"},{\"country\":\"NL\",\"city\":\"Amsterdam\",\"cuts\":[{\"slug\":\"amsterdam-grachtengordel\",\"signature\":true}],\"lesson\":\"The canal ring was speculative property development, dug from 1613 outward in concentric arcs — infrastructure and real estate in one gesture.\"},{\"country\":\"JP\",\"city\":\"Tokyo\",\"cuts\":[{\"slug\":\"tokyo-marunouchi\",\"signature\":true},{\"slug\":\"tokyo-shinjuku\",\"signature\":false}],\"lesson\":\"The void at the centre is the Imperial Palace, and the moats around it are Edo Castle's — the city still bends around a shogun's defences.\"},{\"country\":\"RU\",\"city\":\"Moscow\",\"aliases\":[\"Moskva\"],\"cuts\":[{\"slug\":\"moscow-kremlin\",\"signature\":true}],\"lesson\":\"Moscow is rings and radials because it grew outward from a fortified centre, each ring a former city wall.\"},{\"country\":\"AR\",\"city\":\"Buenos Aires\",\"cuts\":[{\"slug\":\"buenos-aires-microcentro\",\"signature\":true}],\"lesson\":\"The Laws of the Indies fixed a grid and a central plaza for every Spanish colonial city — the same template from California to Patagonia.\"},{\"country\":\"IN\",\"city\":\"New Delhi\",\"aliases\":[\"Delhi\"],\"cuts\":[{\"slug\":\"new-delhi-lutyens\",\"signature\":true}],\"lesson\":\"Lutyens laid imperial hexagons and vistas south of the old city in 1912 — a capital designed to be looked along rather than lived in.\"},{\"country\":\"BR\",\"city\":\"Brasília\",\"aliases\":[\"Brasilia\"],\"cuts\":[{\"slug\":\"brasilia-plano-piloto\",\"signature\":true}],\"lesson\":\"Costa's 1957 Plano Piloto is a single curved axis crossed by a monumental one — a whole capital drawn as one diagram, and almost unwalkable because of it.\"},{\"country\":\"TR\",\"city\":\"Istanbul\",\"cuts\":[{\"slug\":\"istanbul-golden-horn\",\"signature\":true},{\"slug\":\"istanbul-besiktas\",\"signature\":false}],\"lesson\":\"Three bodies of water meet here and the city bought only three bridges across the Bosphorus — a strait is expensive in a way a river is not.\"},{\"country\":\"DE\",\"city\":\"Berlin\",\"cuts\":[{\"slug\":\"berlin-mitte\",\"signature\":true}],\"lesson\":\"The Spree threads Mitte and the blocks change grain mid-street where the Wall stood — a city still legibly stitched from two.\"},{\"country\":\"EG\",\"city\":\"Cairo\",\"aliases\":[\"Al-Qahirah\"],\"cuts\":[{\"slug\":\"cairo-downtown\",\"signature\":true}],\"lesson\":\"Ismail's 1860s downtown is Haussmann copied wholesale beside a medieval city that ignored it, and the Nile's bridges are countable on one hand.\"},{\"country\":\"AU\",\"city\":\"Sydney\",\"cuts\":[{\"slug\":\"sydney-harbour\",\"signature\":true}],\"lesson\":\"A drowned river valley, so the streets answer to headlands rather than a plan, and one bridge does the work of many.\"},{\"country\":\"US\",\"city\":\"Chicago\",\"cuts\":[{\"slug\":\"chicago-loop\",\"signature\":true}],\"lesson\":\"The Loop is named for the elevated railway that rings it, and the grid runs to the Public Land Survey's mile — the whole Midwest on one ruled sheet.\"},{\"country\":\"IT\",\"city\":\"Venice\",\"aliases\":[\"Venezia\"],\"cuts\":[{\"slug\":\"venice-grand-canal\",\"signature\":true}],\"lesson\":\"Built on mudflats with canals for streets, Venice has a fabric that answers to boats — the only major city where the water network outranks the road one.\"},{\"country\":\"US\",\"city\":\"Washington\",\"aliases\":[\"Washington DC\",\"Washington, D.C.\",\"DC\"],\"cuts\":[{\"slug\":\"washington-mall\",\"signature\":true},{\"slug\":\"washington-dupont\",\"signature\":false}],\"lesson\":\"L'Enfant laid diagonal avenues over a grid in 1791 so the new capital would have vistas, and every place the two systems collide became a traffic circle.\"},{\"country\":\"SE\",\"city\":\"Stockholm\",\"cuts\":[{\"slug\":\"stockholm-gamla-stan\",\"signature\":true}],\"lesson\":\"Stockholm is built across fourteen islands where Lake Mälaren meets the Baltic, so almost every route is a bridge and the old town is the plug in the middle.\"},{\"country\":\"KR\",\"city\":\"Seoul\",\"cuts\":[{\"slug\":\"seoul-jongno\",\"signature\":true}],\"lesson\":\"Seoul rebuilt fast after 1953 as superblocks: arterials enclose each block and the interior fills with capillary lanes that connect to nothing else.\"},{\"country\":\"NG\",\"city\":\"Lagos\",\"cuts\":[{\"slug\":\"lagos-island\",\"signature\":true}],\"lesson\":\"Lagos Island was a colonial grid that the city outgrew in every direction, and the lagoon crossings are the bottleneck the whole metropolis is shaped by.\"},{\"country\":\"US\",\"city\":\"Salt Lake City\",\"cuts\":[{\"slug\":\"salt-lake-city-temple\",\"signature\":true}],\"lesson\":\"The Plat of Zion gave Salt Lake City ten-acre blocks and streets wide enough to turn a wagon team — a religious instruction still legible as pure geometry.\"},{\"country\":\"DE\",\"city\":\"Karlsruhe\",\"cuts\":[{\"slug\":\"karlsruhe-schloss\",\"signature\":true}],\"lesson\":\"Thirty-two streets radiate from the palace tower because the margrave wanted every road in his city to point at him.\"},{\"country\":\"RU\",\"city\":\"Saint Petersburg\",\"aliases\":[\"St Petersburg\",\"Sankt-Peterburg\",\"Petersburg\"],\"cuts\":[{\"slug\":\"saint-petersburg-nevsky\",\"signature\":true}],\"lesson\":\"Peter the Great ruled a European grid across the Neva delta from 1703, so the canals are drainage and the avenues are ambition.\"},{\"country\":\"CU\",\"city\":\"Havana\",\"aliases\":[\"La Habana\"],\"cuts\":[{\"slug\":\"havana-vieja\",\"signature\":true}],\"lesson\":\"Havana Vieja is a Laws of the Indies grid bent to its harbour, and the Malecón is the seawall the city later grew a boulevard along.\"},{\"country\":\"FI\",\"city\":\"Helsinki\",\"aliases\":[\"Helsingfors\"],\"cuts\":[{\"slug\":\"helsinki-kruununhaka\",\"signature\":true}],\"lesson\":\"Helsinki was rebuilt on a grid after 1812 to look like an imperial capital, and the sea reaches into it from three sides at once.\"},{\"country\":\"CN\",\"city\":\"Beijing\",\"cuts\":[{\"slug\":\"beijing-centre\",\"signature\":true}],\"lesson\":\"Beijing is a Ming ceremonial diagram: a north-south axis through the Forbidden City, ring roads laid over the vanished walls, and hutong lanes filling the blocks between.\"},{\"country\":\"ES\",\"city\":\"Madrid\",\"cuts\":[{\"slug\":\"madrid-centre\",\"signature\":true}],\"lesson\":\"Madrid grew from a Moorish fort into a Habsburg court city, so the medieval tangle around Plaza Mayor gives way to the ruled Ensanche blocks of the 1860s.\"},{\"country\":\"IT\",\"city\":\"Rome\",\"cuts\":[{\"slug\":\"rome-centre\",\"signature\":true}],\"lesson\":\"Rome's centre is a medieval city poured into an ancient one: streets bend around the Pantheon and Piazza Navona still traces the outline of Domitian's stadium.\"},{\"country\":\"CA\",\"city\":\"Ottawa\",\"cuts\":[{\"slug\":\"ottawa-centre\",\"signature\":true}],\"lesson\":\"The Rideau Canal was cut in the 1820s as a military bypass of the St Lawrence, and Ottawa grew along it — the waterway came first and the capital followed.\"},{\"country\":\"NO\",\"city\":\"Oslo\",\"cuts\":[{\"slug\":\"oslo-centre\",\"signature\":true}],\"lesson\":\"Christian IV rebuilt Oslo on a grid in 1624 after fire took the medieval town, and the fjord's head still decides where every street can run.\"},{\"country\":\"MX\",\"city\":\"Mexico City\",\"cuts\":[{\"slug\":\"mexico-city-centre\",\"signature\":true}],\"lesson\":\"The Zócalo sits on the ruins of Tenochtitlan's sacred precinct: the Spanish grid was laid over an Aztec island city, and the lake beneath is why the ground still sinks.\"},{\"country\":\"CZ\",\"city\":\"Prague\",\"cuts\":[{\"slug\":\"prague-centre\",\"signature\":true}],\"lesson\":\"The Vltava splits Prague into castle and town, and the Charles Bridge held a monopoly on crossing it for five hundred years.\"},{\"country\":\"PL\",\"city\":\"Warsaw\",\"cuts\":[{\"slug\":\"warsaw-centre\",\"signature\":true}],\"lesson\":\"Warsaw's old town is a 1950s reconstruction of what the Wehrmacht demolished in 1944 — the medieval plan rebuilt deliberately, from Canaletto's paintings.\"},{\"country\":\"ID\",\"city\":\"Jakarta\",\"cuts\":[{\"slug\":\"jakarta-centre\",\"signature\":true}],\"lesson\":\"Batavia was built as a Dutch canal town on the equator, and the canals that killed its colonists with malaria still thread the old city.\"},{\"country\":\"AU\",\"city\":\"Canberra\",\"cuts\":[{\"slug\":\"canberra-centre\",\"signature\":true}],\"lesson\":\"Griffin won the 1912 competition with a geometry of circles and axes aimed at the hills — a capital designed whole, before anyone lived in it.\"},{\"country\":\"IR\",\"city\":\"Tehran\",\"cuts\":[{\"slug\":\"tehran-centre\",\"signature\":true}],\"lesson\":\"Tehran climbs from the desert plain into the Alborz foothills, so its long avenues run north-south with the slope and the wealthy live uphill.\"},{\"country\":\"AT\",\"city\":\"Vienna\",\"cuts\":[{\"slug\":\"vienna-centre\",\"signature\":true}],\"lesson\":\"The Ringstrasse is the city wall: Franz Joseph ordered the fortifications demolished in 1857 and a boulevard of public palaces built on the cleared ground.\"},{\"country\":\"CH\",\"city\":\"Bern\",\"cuts\":[{\"slug\":\"bern-centre\",\"signature\":true}],\"lesson\":\"Bern sits in a tight loop of the Aare, and the medieval town simply fills the peninsula the river left — defence by geography.\"},{\"country\":\"BE\",\"city\":\"Brussels\",\"cuts\":[{\"slug\":\"brussels-centre\",\"signature\":true}],\"lesson\":\"The Grand-Place is the hub of a medieval street web, and the Senne that once ran through it was vaulted over in the 1860s and turned into boulevards.\"},{\"country\":\"NZ\",\"city\":\"Wellington\",\"cuts\":[{\"slug\":\"wellington-centre\",\"signature\":true}],\"lesson\":\"Wellington is pinned between harbour and fault-line hills, so its centre is built partly on land the 1855 earthquake lifted out of the sea.\"},{\"country\":\"DK\",\"city\":\"Copenhagen\",\"cuts\":[{\"slug\":\"copenhagen-centre\",\"signature\":true}],\"lesson\":\"Copenhagen's centre is a ring of star-fort ramparts turned into parks and lakes, with a dense medieval core behind them.\"},{\"country\":\"IE\",\"city\":\"Dublin\",\"cuts\":[{\"slug\":\"dublin-centre\",\"signature\":true}],\"lesson\":\"The Liffey divides Georgian Dublin, and the Wide Streets Commission cut straight avenues through the medieval fabric from 1757 to make it a modern capital.\"},{\"country\":\"UA\",\"city\":\"Kyiv\",\"cuts\":[{\"slug\":\"kyiv-centre\",\"signature\":true}],\"lesson\":\"Kyiv stands on the Dnieper's high right bank, and Khreshchatyk runs along a filled ravine — the valley decided the city's main street.\"},{\"country\":\"TR\",\"city\":\"Ankara\",\"cuts\":[{\"slug\":\"ankara-centre\",\"signature\":false}],\"lesson\":\"Ankara was a provincial town of 20,000 when Atatürk made it capital in 1923; the planned grid to the south is deliberately unlike the citadel hill it replaced.\"},{\"country\":\"TW\",\"city\":\"Taipei\",\"cuts\":[{\"slug\":\"taipei-centre\",\"signature\":true}],\"lesson\":\"Taipei's walled Qing city was demolished by the Japanese in 1904 and replaced with boulevards — the wall's footprint is now a rectangle of wide roads.\"},{\"country\":\"RO\",\"city\":\"Bucharest\",\"cuts\":[{\"slug\":\"bucharest-centre\",\"signature\":true}],\"lesson\":\"Ceaușescu levelled a fifth of old Bucharest in the 1980s for the Centrul Civic, and its monumental axis cuts across the older organic streets.\"},{\"country\":\"HU\",\"city\":\"Budapest\",\"cuts\":[{\"slug\":\"budapest-centre\",\"signature\":true}],\"lesson\":\"Buda's hills and Pest's flat plain were separate cities until 1873, and the Danube between them is bridged in a deliberate ceremonial sequence.\"},{\"country\":\"GR\",\"city\":\"Athens\",\"cuts\":[{\"slug\":\"athens-centre\",\"signature\":true}],\"lesson\":\"The 1833 plan laid a neoclassical triangle between the Acropolis and the new palace, and Plaka's lanes below the rock are what survived from Ottoman Athens.\"},{\"country\":\"PT\",\"city\":\"Lisbon\",\"cuts\":[{\"slug\":\"lisbon-centre\",\"signature\":true}],\"lesson\":\"The Baixa is Europe's first earthquake-resistant grid: Pombal rebuilt it on a strict rectangle after the 1755 quake, framed by hills that kept their old streets.\"},{\"country\":\"MY\",\"city\":\"Kuala Lumpur\",\"cuts\":[{\"slug\":\"kuala-lumpur-centre\",\"signature\":true}],\"lesson\":\"Kuala Lumpur means 'muddy confluence', and the city began exactly where the Klang and Gombak rivers meet — the tin-mining camp's junction is still its centre.\"},{\"country\":\"TH\",\"city\":\"Bangkok\",\"cuts\":[{\"slug\":\"bangkok-centre\",\"signature\":true}],\"lesson\":\"Rattanakosin island was cut from the mainland by canals in 1782 to make a defensible royal city, and the khlong network was Bangkok's road system for a century.\"},{\"country\":\"PE\",\"city\":\"Lima\",\"cuts\":[{\"slug\":\"lima-centre\",\"signature\":true}],\"lesson\":\"Pizarro laid Lima out in 1535 on the Laws of the Indies grid, and the Rímac's valley walls are what finally stopped it spreading.\"},{\"country\":\"CL\",\"city\":\"Santiago\",\"cuts\":[{\"slug\":\"santiago-centre\",\"signature\":true}],\"lesson\":\"Santiago's grid was staked out in 1541 between the Mapocho and a hill, and the Alameda follows the river channel the Spanish filled in.\"},{\"country\":\"CO\",\"city\":\"Bogotá\",\"cuts\":[{\"slug\":\"bogota-centre\",\"signature\":true}],\"lesson\":\"Bogotá is a colonial grid pressed against the Andean escarpment: the mountains stop it dead to the east, so the city could only grow north and south.\"},{\"country\":\"PH\",\"city\":\"Manila\",\"cuts\":[{\"slug\":\"manila-centre\",\"signature\":true}],\"lesson\":\"Intramuros is a Spanish walled city with its own moat, and the Pasig separating it from the rest of Manila is why the old town still reads as a fortress.\"},{\"country\":\"VN\",\"city\":\"Hanoi\",\"cuts\":[{\"slug\":\"hanoi-centre\",\"signature\":true}],\"lesson\":\"Hanoi's Old Quarter is the 36 guild streets, each once a single trade, and the French laid a boulevard grid beside it rather than through it.\"},{\"country\":\"SG\",\"city\":\"Singapore\",\"cuts\":[{\"slug\":\"singapore-centre\",\"signature\":true}],\"lesson\":\"Raffles' 1822 plan zoned Singapore by ethnicity into separate quarters, and the Singapore River between them was the port that paid for all of it.\"},{\"country\":\"RS\",\"city\":\"Belgrade\",\"cuts\":[{\"slug\":\"belgrade-centre\",\"signature\":true}],\"lesson\":\"Belgrade's fortress sits exactly where the Sava meets the Danube, which is why the city has been besieged more often than almost any other in Europe.\"},{\"country\":\"HR\",\"city\":\"Zagreb\",\"cuts\":[{\"slug\":\"zagreb-centre\",\"signature\":true}],\"lesson\":\"Zagreb's Lower Town is the Green Horseshoe — a U of parks and public buildings laid out in the 1880s below the two medieval hill settlements.\"},{\"country\":\"BD\",\"city\":\"Dhaka\",\"cuts\":[{\"slug\":\"dhaka-centre\",\"signature\":true}],\"lesson\":\"Old Dhaka's lanes were laid for Mughal river trade on the Buriganga, and the planned blocks north of them are twentieth-century additions to a river city.\"},{\"country\":\"KZ\",\"city\":\"Astana\",\"cuts\":[{\"slug\":\"astana-centre\",\"signature\":true}],\"lesson\":\"Astana's left bank was empty steppe until 1997: Kurokawa's plan runs one monumental axis from the presidential palace, built whole in two decades.\"},{\"country\":\"UY\",\"city\":\"Montevideo\",\"cuts\":[{\"slug\":\"montevideo-centre\",\"signature\":true}],\"lesson\":\"Montevideo's Ciudad Vieja is a grid on a peninsula guarding the bay, and the Rambla wraps the whole waterfront as a single continuous road.\"},{\"country\":\"KE\",\"city\":\"Nairobi\",\"cuts\":[{\"slug\":\"nairobi-centre\",\"signature\":true}],\"lesson\":\"Nairobi began in 1899 as a railway depot on swampy ground, and the yards where the line halted are still the seam its street grid bends around.\"},{\"country\":\"ZA\",\"city\":\"Pretoria\",\"cuts\":[{\"slug\":\"pretoria-centre\",\"signature\":true}],\"lesson\":\"Herbert Baker set the Union Buildings on a hillside above Pretoria in 1910 so the government would look down a formal axis at the city it governed.\"},{\"country\":\"MA\",\"city\":\"Rabat\",\"cuts\":[{\"slug\":\"rabat-centre\",\"signature\":true}],\"lesson\":\"Rabat has a walled medina and, beside it, Lyautey's 1912 French ville nouvelle — colonial policy was to build alongside the old city rather than through it.\"},{\"country\":\"IL\",\"city\":\"Jerusalem\",\"cuts\":[{\"slug\":\"jerusalem-centre\",\"signature\":true}],\"lesson\":\"The Old City's quarters sit inside Suleiman's 1538 walls, and the grid outside them is nineteenth-century expansion once building beyond the gates became safe.\"},{\"country\":\"SI\",\"city\":\"Ljubljana\",\"cuts\":[{\"slug\":\"ljubljana-centre\",\"signature\":true}],\"lesson\":\"Plečnik reshaped Ljubljana between the wars as a single architectural work, treating the Ljubljanica's embankments and bridges as the city's spine.\"},{\"country\":\"BY\",\"city\":\"Minsk\",\"cuts\":[{\"slug\":\"minsk-centre\",\"signature\":true}],\"lesson\":\"Minsk was rebuilt almost entirely after 1944, so its centre is a Stalinist ensemble: one monumental avenue, and superblocks rather than streets.\"},{\"country\":\"AM\",\"city\":\"Yerevan\",\"cuts\":[{\"slug\":\"yerevan-centre\",\"signature\":true}],\"lesson\":\"Tamanian's 1924 plan wrapped Yerevan in a ring boulevard around a radial core, and the pink tuff it is faced in came from the same quarries throughout.\"},{\"country\":\"SK\",\"city\":\"Bratislava\",\"cuts\":[{\"slug\":\"bratislava-centre\",\"signature\":true}],\"lesson\":\"Bratislava's old town is a compact medieval core under a castle hill, cut through in the 1970s by a motorway and bridge that took part of the Jewish quarter.\"},{\"country\":\"BG\",\"city\":\"Sofia\",\"cuts\":[{\"slug\":\"sofia-centre\",\"signature\":true}],\"lesson\":\"Sofia's yellow-paved centre is a planned 1880s capital laid over Roman Serdica, whose street grid is still visible in the excavations beneath it.\"},{\"country\":\"LT\",\"city\":\"Vilnius\",\"cuts\":[{\"slug\":\"vilnius-centre\",\"signature\":true}],\"lesson\":\"Vilnius has one of Europe's largest surviving Gothic old towns, its lanes curving to the Neris and Vilnia rivers rather than to any plan.\"},{\"country\":\"EE\",\"city\":\"Tallinn\",\"cuts\":[{\"slug\":\"tallinn-centre\",\"signature\":true}],\"lesson\":\"Tallinn's upper and lower towns are two separate walled settlements — nobility on the limestone hill, merchants below — with the Hanseatic wall still around both.\"},{\"country\":\"LV\",\"city\":\"Riga\",\"cuts\":[{\"slug\":\"riga-centre\",\"signature\":true}],\"lesson\":\"Riga's medieval core is ringed by a park where the ramparts were, and beyond it stands the densest collection of Art Nouveau buildings in Europe.\"},{\"country\":\"VE\",\"city\":\"Caracas\",\"cuts\":[{\"slug\":\"caracas-centre\",\"signature\":true}],\"lesson\":\"Caracas fills a narrow valley under the Ávila, so it can only grow east and west, and the motorway down its length is the city's only through route.\"},{\"country\":\"DZ\",\"city\":\"Algiers\",\"cuts\":[{\"slug\":\"algiers-centre\",\"signature\":true}],\"lesson\":\"The Casbah tumbles down its hillside in stepped lanes no vehicle can climb, and the French built an arcaded waterfront below it after 1830.\"},{\"country\":\"UG\",\"city\":\"Kampala\",\"cuts\":[{\"slug\":\"kampala-centre\",\"signature\":false}],\"lesson\":\"Kampala was built across seven hills, each historically a different institution's, so its road network radiates from hilltop to hilltop.\"},{\"country\":\"AF\",\"city\":\"Kabul\",\"cuts\":[{\"slug\":\"kabul-centre\",\"signature\":false}],\"lesson\":\"Kabul sits in a bowl between mountains on the old road to India, and the Kabul river through the middle is the line the bazaars grew along.\"},{\"country\":\"MK\",\"city\":\"Skopje\",\"cuts\":[{\"slug\":\"skopje-centre\",\"signature\":true}],\"lesson\":\"After the 1963 earthquake Skopje was rebuilt to Kenzō Tange's plan, so a brutalist centre stands directly across the Vardar from an Ottoman bazaar.\"},{\"country\":\"BA\",\"city\":\"Sarajevo\",\"cuts\":[{\"slug\":\"sarajevo-centre\",\"signature\":true}],\"lesson\":\"Sarajevo runs along a single valley, and you can walk from Ottoman bazaar to Austro-Hungarian boulevard in one straight line where the two empires met.\"},{\"country\":\"MM\",\"city\":\"Naypyidaw\",\"cuts\":[{\"slug\":\"naypyidaw-centre\",\"signature\":true}],\"lesson\":\"Naypyidaw was built from nothing after 2005 with twenty-lane highways and no crowds — a capital laid out at a scale its population has never filled.\"},{\"country\":\"CD\",\"city\":\"Kinshasa\",\"cuts\":[{\"slug\":\"kinshasa-centre\",\"signature\":true}],\"lesson\":\"Kinshasa faces Brazzaville across the Congo, the only place on earth where two national capitals sit within sight of each other.\"},{\"country\":\"AO\",\"city\":\"Luanda\",\"cuts\":[{\"slug\":\"luanda-centre\",\"signature\":true}],\"lesson\":\"Luanda's colonial core wraps a bay behind a sand spit, and the Marginal along the water is the city's ceremonial front.\"},{\"country\":\"ET\",\"city\":\"Addis Ababa\",\"cuts\":[{\"slug\":\"addis-ababa-centre\",\"signature\":false}],\"lesson\":\"Addis Ababa was founded in 1886 around Menelik's palace on high ground, and its roads still radiate from that compound rather than from any grid.\"},{\"country\":\"GH\",\"city\":\"Accra\",\"cuts\":[{\"slug\":\"accra-centre\",\"signature\":false}],\"lesson\":\"Accra grew from three separate coastal forts — Danish, Dutch and British — which is why its old districts still read as distinct towns.\"},{\"country\":\"TZ\",\"city\":\"Dodoma\",\"cuts\":[{\"slug\":\"dodoma-centre\",\"signature\":false}],\"lesson\":\"Dodoma was made capital in 1974 to move government inland from Dar es Salaam, and its wide planned avenues are still filling in.\"},{\"country\":\"SN\",\"city\":\"Dakar\",\"cuts\":[{\"slug\":\"dakar-centre\",\"signature\":true}],\"lesson\":\"Dakar sits on the westernmost point of Africa, and the Plateau's colonial grid ends abruptly at cliffs above the Atlantic.\"},{\"country\":\"CI\",\"city\":\"Yamoussoukro\",\"cuts\":[{\"slug\":\"yamoussoukro-centre\",\"signature\":false}],\"lesson\":\"Yamoussoukro was Houphouët-Boigny's home village, made capital in 1983 and given motorway-width boulevards for a population that never arrived.\"},{\"country\":\"PA\",\"city\":\"Panama City\",\"cuts\":[{\"slug\":\"panama-city-centre\",\"signature\":true}],\"lesson\":\"Casco Viejo was rebuilt on a defensible peninsula in 1673 after pirates burned the first city, and the canal's Pacific entrance is its reason for existing.\"},{\"country\":\"CR\",\"city\":\"San José\",\"cuts\":[{\"slug\":\"san-jose-centre\",\"signature\":false}],\"lesson\":\"San José is a colonial grid on the Central Valley floor, laid out where the coffee estates that funded the country met.\"},{\"country\":\"GT\",\"city\":\"Guatemala City\",\"cuts\":[{\"slug\":\"guatemala-city-centre\",\"signature\":true}],\"lesson\":\"Guatemala City was founded in 1776 after earthquakes destroyed Antigua, and its grid is numbered by zone rather than named.\"},{\"country\":\"EC\",\"city\":\"Quito\",\"cuts\":[{\"slug\":\"quito-centre\",\"signature\":true}],\"lesson\":\"Quito runs 40km along a narrow Andean shelf at 2,850m, so the colonial centre is a grid squeezed between volcano slopes.\"},{\"country\":\"BO\",\"city\":\"La Paz\",\"cuts\":[{\"slug\":\"la-paz-centre\",\"signature\":true}],\"lesson\":\"La Paz is built inside a canyon to shelter from the altiplano wind, and its streets climb the walls so steeply that cable cars became public transport.\"},{\"country\":\"PY\",\"city\":\"Asunción\",\"cuts\":[{\"slug\":\"asuncion-centre\",\"signature\":false}],\"lesson\":\"Asunción's grid faces the Paraguay river, the highway that made it the first Spanish base in the region.\"},{\"country\":\"JO\",\"city\":\"Amman\",\"cuts\":[{\"slug\":\"amman-centre\",\"signature\":false}],\"lesson\":\"Amman is built over nineteen hills around a Roman theatre, and its downtown sits in the wadi where all the slopes drain.\"},{\"country\":\"LB\",\"city\":\"Beirut\",\"cuts\":[{\"slug\":\"beirut-centre\",\"signature\":true}],\"lesson\":\"Beirut's centre was rebuilt after 1990 on the Green Line that had split the city for fifteen years — the war's dividing street became a boulevard.\"},{\"country\":\"QA\",\"city\":\"Doha\",\"cuts\":[{\"slug\":\"doha-centre\",\"signature\":true}],\"lesson\":\"Doha's Corniche curves around a dredged bay, and West Bay's towers stand on land that was seabed within living memory.\"},{\"country\":\"AE\",\"city\":\"Abu Dhabi\",\"cuts\":[{\"slug\":\"abu-dhabi-centre\",\"signature\":true}],\"lesson\":\"Abu Dhabi is a 1960s grid on an island, laid out with superblocks wide enough that the interiors became their own neighbourhoods.\"},{\"country\":\"KW\",\"city\":\"Kuwait City\",\"cuts\":[{\"slug\":\"kuwait-city-centre\",\"signature\":true}],\"lesson\":\"Kuwait City's ring roads trace the mud wall demolished in 1957, so the old town's footprint survives as motorway geometry.\"},{\"country\":\"SA\",\"city\":\"Riyadh\",\"cuts\":[{\"slug\":\"riyadh-centre\",\"signature\":false}],\"lesson\":\"Riyadh's Diriyah roots are mud-brick, but the modern city is a superblock grid across open desert with no geography to bend it.\"},{\"country\":\"UZ\",\"city\":\"Tashkent\",\"cuts\":[{\"slug\":\"tashkent-centre\",\"signature\":true}],\"lesson\":\"Tashkent was rebuilt after the 1966 earthquake as a Soviet showcase, so wide avenues and microdistricts sit beside the surviving old-town mahallas.\"},{\"country\":\"AZ\",\"city\":\"Baku\",\"cuts\":[{\"slug\":\"baku-centre\",\"signature\":true}],\"lesson\":\"Baku's walled Icherisheher stands on a bay, ringed by oil-boom mansions built when the city produced half the world's petroleum.\"},{\"country\":\"GE\",\"city\":\"Tbilisi\",\"cuts\":[{\"slug\":\"tbilisi-centre\",\"signature\":true}],\"lesson\":\"Tbilisi is squeezed into the Kura gorge, and its old town's balconied houses step up the valley sides because there is nowhere flat to build.\"},{\"country\":\"NP\",\"city\":\"Kathmandu\",\"cuts\":[{\"slug\":\"kathmandu-centre\",\"signature\":true}],\"lesson\":\"Kathmandu's Durbar Square is the centre of a medieval Newar city, its lanes woven between courtyards rather than laid out along streets.\"},{\"country\":\"LK\",\"city\":\"Colombo\",\"cuts\":[{\"slug\":\"colombo-centre\",\"signature\":false}],\"lesson\":\"Colombo's Fort and Pettah are Dutch and British layers on a natural harbour, with the Beira Lake behind them as the old defensive water.\"},{\"country\":\"MN\",\"city\":\"Ulaanbaatar\",\"aliases\":[\"Ulan Bator\"],\"cuts\":[{\"slug\":\"ulaanbaatar-centre\",\"signature\":true}],\"lesson\":\"Ulaanbaatar was a movable monastery town until the 1920s; the Soviet grid at its centre is ringed by ger districts that kept the older pattern.\"},{\"country\":\"KH\",\"city\":\"Phnom Penh\",\"cuts\":[{\"slug\":\"phnom-penh-centre\",\"signature\":true}],\"lesson\":\"Phnom Penh sits at the confluence where the Mekong meets the Tonlé Sap, a river that reverses direction twice a year.\"},{\"country\":\"LA\",\"city\":\"Vientiane\",\"cuts\":[{\"slug\":\"vientiane-centre\",\"signature\":false}],\"lesson\":\"Vientiane spreads along one bank of the Mekong, with Lan Xang Avenue driven through as a ceremonial axis in the 1950s.\"},{\"country\":\"NG\",\"city\":\"Abuja\",\"cuts\":[{\"slug\":\"abuja-centre\",\"signature\":true}],\"lesson\":\"Abuja was planned from 1980 to replace Lagos with a neutral federal capital, its axis aimed squarely at the granite monolith of Aso Rock.\"},{\"country\":\"YE\",\"city\":\"Sanaa\",\"cuts\":[{\"slug\":\"sanaa-centre\",\"signature\":true}],\"lesson\":\"Sanaa's old city has been inhabited for 2,500 years, its tower houses of rammed earth and gypsum stacked six storeys inside a surviving wall.\"},{\"country\":\"CM\",\"city\":\"Yaoundé\",\"cuts\":[{\"slug\":\"yaounde-centre\",\"signature\":false}],\"lesson\":\"Yaoundé is spread over seven hills, so its roads wind along contours and the valleys between them flood in the rains.\"},{\"country\":\"IS\",\"city\":\"Reykjavík\",\"cuts\":[{\"slug\":\"reykjavik-centre\",\"signature\":true}],\"lesson\":\"Reykjavík is the world's northernmost capital, its old centre a small grid of timber and corrugated iron between a pond and the harbour.\"},{\"country\":\"TN\",\"city\":\"Tunis\",\"cuts\":[{\"slug\":\"tunis-centre\",\"signature\":true}],\"lesson\":\"Tunis pairs a UNESCO medina of covered souks with a French ville nouvelle whose Avenue Habib Bourguiba was built on a filled lagoon.\"},{\"country\":\"IQ\",\"city\":\"Baghdad\",\"cuts\":[{\"slug\":\"baghdad-centre\",\"signature\":true}],\"lesson\":\"Baghdad was founded in 762 as a perfectly circular city; nothing of that plan survives, but the Tigris through the middle still orders everything.\"},{\"country\":\"SY\",\"city\":\"Damascus\",\"cuts\":[{\"slug\":\"damascus-centre\",\"signature\":true}],\"lesson\":\"Damascus claims the longest continuous habitation of any city, and the Street Called Straight still runs the line the Romans gave it.\"},{\"country\":\"AL\",\"city\":\"Tirana\",\"cuts\":[{\"slug\":\"tirana-centre\",\"signature\":true}],\"lesson\":\"Tirana's centre is an Italian rationalist axis from the 1930s, its buildings later painted in blocks of colour to lift a grey socialist city.\"},{\"country\":\"DO\",\"city\":\"Santo Domingo\",\"cuts\":[{\"slug\":\"santo-domingo-centre\",\"signature\":true}],\"lesson\":\"Santo Domingo's Zona Colonial is the oldest permanent European settlement in the Americas, and its grid became the template for Spanish colonial towns.\"},{\"country\":\"SD\",\"city\":\"Khartoum\",\"cuts\":[{\"slug\":\"khartoum-centre\",\"signature\":true}],\"lesson\":\"Khartoum sits exactly where the Blue and White Niles meet, and Kitchener is said to have laid its streets in a Union Jack pattern.\"},{\"country\":\"ZW\",\"city\":\"Harare\",\"cuts\":[{\"slug\":\"harare-centre\",\"signature\":false}],\"lesson\":\"Harare was laid out in 1890 as a colonial grid on the Mashonaland plateau, its blocks generous because land was taken as unlimited.\"},{\"country\":\"LU\",\"city\":\"Luxembourg\",\"cuts\":[{\"slug\":\"luxembourg-centre\",\"signature\":true}],\"lesson\":\"Luxembourg City is built around deep gorges cut by the Alzette, and its fortress walls used the cliffs themselves as ramparts.\"},{\"country\":\"CY\",\"city\":\"Nicosia\",\"cuts\":[{\"slug\":\"nicosia-centre\",\"signature\":true}],\"lesson\":\"Nicosia is the last divided capital in Europe, its Venetian star-fort walls enclosing a centre split by a buffer zone since 1974.\"},{\"country\":\"BF\",\"city\":\"Ouagadougou\",\"cuts\":[{\"slug\":\"ouagadougou-centre\",\"signature\":false}],\"lesson\":\"Ouagadougou grew outward from a royal Mossi compound, so a colonial grid sits over an older radial pattern of neighbourhoods.\"},{\"country\":\"LY\",\"city\":\"Tripoli\",\"cuts\":[{\"slug\":\"tripoli-centre\",\"signature\":true}],\"lesson\":\"Tripoli's walled medina stands beside a Roman arch and an Italian colonial waterfront, three occupations layered on one harbour.\"},{\"country\":\"MD\",\"city\":\"Chișinău\",\"cuts\":[{\"slug\":\"chisinau-centre\",\"signature\":true}],\"lesson\":\"Chișinău was laid out on a Russian imperial grid in the 1830s and rebuilt after 1944, its streets unusually wide and green for the region.\"},{\"country\":\"ZM\",\"city\":\"Lusaka\",\"cuts\":[{\"slug\":\"lusaka-centre\",\"signature\":false}],\"lesson\":\"Lusaka was planned as a garden city in 1931 around a single main road, and Cairo Road is still the axis everything else answers to.\"},{\"country\":\"KG\",\"city\":\"Bishkek\",\"cuts\":[{\"slug\":\"bishkek-centre\",\"signature\":true}],\"lesson\":\"Bishkek is a Russian military grid from 1878, laid with irrigation channels along every street so the steppe city could keep its trees.\"},{\"country\":\"ME\",\"city\":\"Podgorica\",\"cuts\":[{\"slug\":\"podgorica-centre\",\"signature\":false}],\"lesson\":\"Podgorica sits where five rivers meet, rebuilt almost entirely after 1944 bombing, so its centre is post-war rather than Ottoman.\"},{\"country\":\"MZ\",\"city\":\"Maputo\",\"cuts\":[{\"slug\":\"maputo-centre\",\"signature\":true}],\"lesson\":\"Maputo's Baixa is a Portuguese grid on a bay, its streets named for revolutionaries after independence but their geometry unchanged.\"},{\"country\":\"MG\",\"city\":\"Antananarivo\",\"cuts\":[{\"slug\":\"antananarivo-centre\",\"signature\":true}],\"lesson\":\"Antananarivo means 'city of a thousand', and it climbs a long ridge in stairways because the royal palace claimed the summit.\"},{\"country\":\"HN\",\"city\":\"Tegucigalpa\",\"cuts\":[{\"slug\":\"tegucigalpa-centre\",\"signature\":false}],\"lesson\":\"Tegucigalpa is wrapped around hills and split by the Choluteca river from its twin Comayagüela — one capital that was two towns.\"},{\"country\":\"KP\",\"city\":\"Pyongyang\",\"cuts\":[{\"slug\":\"pyongyang-centre\",\"signature\":true}],\"lesson\":\"Pyongyang was rebuilt from almost nothing after 1953 as a socialist showpiece: monumental axes, vast plazas, and towers set to be seen from them.\"},{\"country\":\"CG\",\"city\":\"Brazzaville\",\"cuts\":[{\"slug\":\"brazzaville-centre\",\"signature\":true}],\"lesson\":\"Brazzaville faces Kinshasa across the Congo rapids, and the pool between them is why both cities exist where the river stops being navigable.\"},{\"country\":\"HT\",\"city\":\"Port-au-Prince\",\"cuts\":[{\"slug\":\"port-au-prince-centre\",\"signature\":false}],\"lesson\":\"Port-au-Prince is a grid on a bay backed by steep hills, much of it rebuilt after the 2010 earthquake levelled the centre.\"},{\"country\":\"MT\",\"city\":\"Valletta\",\"cuts\":[{\"slug\":\"valletta-centre\",\"signature\":true}],\"lesson\":\"Valletta is a 1566 grid on a fortified peninsula, laid out by the Knights so sea breezes would run straight down every street.\"},{\"country\":\"ML\",\"city\":\"Bamako\",\"cuts\":[{\"slug\":\"bamako-centre\",\"signature\":false}],\"lesson\":\"Bamako spreads along both banks of the Niger, and the bridges over it are the bottleneck the whole city queues for.\"},{\"country\":\"SO\",\"city\":\"Mogadishu\",\"cuts\":[{\"slug\":\"mogadishu-centre\",\"signature\":false}],\"lesson\":\"Mogadishu's Hamar Weyne is a medieval Swahili-coast trading quarter of coral-stone lanes, beside an Italian colonial grid.\"},{\"country\":\"RW\",\"city\":\"Kigali\",\"cuts\":[{\"slug\":\"kigali-centre\",\"signature\":true}],\"lesson\":\"Kigali is built across a series of ridges and valleys, so its roads run along the crests and the marshland below stays largely unbuilt.\"},{\"country\":\"NE\",\"city\":\"Niamey\",\"cuts\":[{\"slug\":\"niamey-centre\",\"signature\":false}],\"lesson\":\"Niamey sits on the Niger's left bank, a colonial grid that grew from a fishing village once the French made it a capital in 1926.\"},{\"country\":\"MW\",\"city\":\"Lilongwe\",\"cuts\":[{\"slug\":\"lilongwe-centre\",\"signature\":false}],\"lesson\":\"Lilongwe was made capital in 1975 and built as two separate centres — old town and city centre — deliberately kept apart by a nature reserve.\"},{\"country\":\"XK\",\"city\":\"Pristina\",\"cuts\":[{\"slug\":\"pristina-centre\",\"signature\":false}],\"lesson\":\"Pristina's Ottoman core was largely cleared under Yugoslav planning, leaving modernist blocks where the old bazaar quarter stood.\"},{\"country\":\"JM\",\"city\":\"Kingston\",\"cuts\":[{\"slug\":\"kingston-centre\",\"signature\":true}],\"lesson\":\"Kingston was laid out on a grid in 1692 for refugees from the earthquake that sank Port Royal across the harbour.\"},{\"country\":\"NI\",\"city\":\"Managua\",\"cuts\":[{\"slug\":\"managua-centre\",\"signature\":false}],\"lesson\":\"Managua has no real downtown: the 1972 earthquake destroyed it and the centre was never rebuilt, leaving open ground at the city's heart.\"},{\"country\":\"BW\",\"city\":\"Gaborone\",\"cuts\":[{\"slug\":\"gaborone-centre\",\"signature\":false}],\"lesson\":\"Gaborone was built from scratch in three years before independence in 1966, arranged around a central mall rather than a colonial grid.\"},{\"country\":\"TJ\",\"city\":\"Dushanbe\",\"cuts\":[{\"slug\":\"dushanbe-centre\",\"signature\":true}],\"lesson\":\"Dushanbe means 'Monday', after the village market that stood here before the Soviets built a capital on a single tree-lined avenue.\"},{\"country\":\"NA\",\"city\":\"Windhoek\",\"cuts\":[{\"slug\":\"windhoek-centre\",\"signature\":false}],\"lesson\":\"Windhoek's Independence Avenue runs the length of a valley between hills, with German colonial buildings still lining the centre.\"},{\"country\":\"GA\",\"city\":\"Libreville\",\"cuts\":[{\"slug\":\"libreville-centre\",\"signature\":false}],\"lesson\":\"Libreville was founded for freed slaves in 1849 and grew along the estuary shore, so it is long, thin and entirely coastal.\"},{\"country\":\"SR\",\"city\":\"Paramaribo\",\"cuts\":[{\"slug\":\"paramaribo-centre\",\"signature\":true}],\"lesson\":\"Paramaribo's historic centre is Dutch colonial timber architecture on a grid, laid along a bend of the Suriname river.\"},{\"country\":\"TT\",\"city\":\"Port of Spain\",\"cuts\":[{\"slug\":\"port-of-spain-centre\",\"signature\":false}],\"lesson\":\"Port of Spain's grid runs from the waterfront to the Queen's Park Savannah, a former sugar estate kept as open ground.\"},{\"country\":\"MR\",\"city\":\"Nouakchott\",\"cuts\":[{\"slug\":\"nouakchott-centre\",\"signature\":false}],\"lesson\":\"Nouakchott was a village of a few hundred when chosen as capital in 1958, and its grid has been advancing into the Sahara ever since.\"},{\"country\":\"SL\",\"city\":\"Freetown\",\"cuts\":[{\"slug\":\"freetown-centre\",\"signature\":false}],\"lesson\":\"Freetown was settled in 1792 by freed slaves from Nova Scotia, its grid pressed between mountains and one of the world's largest natural harbours.\"},{\"country\":\"BS\",\"city\":\"Nassau\",\"cuts\":[{\"slug\":\"nassau-centre\",\"signature\":true}],\"lesson\":\"Nassau's harbour is sheltered by Paradise Island, and the colonial grid behind it climbs to forts built against the pirates who once ran the town.\"},{\"country\":\"DJ\",\"city\":\"Djibouti\",\"cuts\":[{\"slug\":\"djibouti-centre\",\"signature\":true}],\"lesson\":\"Djibouti City exists for its port at the mouth of the Red Sea, and the European Quarter's grid faces the harbour it was built to serve.\"},{\"country\":\"GY\",\"city\":\"Georgetown\",\"cuts\":[{\"slug\":\"georgetown-centre\",\"signature\":true}],\"lesson\":\"Georgetown lies below sea level behind a seawall, drained by Dutch-built canals that still run down the middle of its widest streets.\"},{\"country\":\"AD\",\"city\":\"Andorra la Vella\",\"cuts\":[{\"slug\":\"andorra-la-vella-centre\",\"signature\":true}],\"lesson\":\"Andorra la Vella is the highest capital in Europe, wedged so tightly into its valley that the town is essentially one long street.\"},{\"country\":\"MC\",\"city\":\"Monaco\",\"cuts\":[{\"slug\":\"monaco-centre\",\"signature\":true}],\"lesson\":\"Monaco is built up a cliff face in terraces, and its street circuit is simply the public roads that thread between them.\"},{\"country\":\"MU\",\"city\":\"Port Louis\",\"cuts\":[{\"slug\":\"port-louis-centre\",\"signature\":true}],\"lesson\":\"Port Louis sits in an amphitheatre of mountains around a harbour, its French colonial grid hemmed in on every landward side.\"},{\"country\":\"BH\",\"city\":\"Manama\",\"cuts\":[{\"slug\":\"manama-centre\",\"signature\":true}],\"lesson\":\"Manama's old souk backs onto a financial district built almost entirely on reclaimed land — the coastline has moved within one lifetime.\"},{\"country\":\"TG\",\"city\":\"Lomé\",\"cuts\":[{\"slug\":\"lome-centre\",\"signature\":false}],\"lesson\":\"Lomé sits right on the Ghanaian border with its port beside the centre, so the city trades across a frontier it can walk to.\"},{\"country\":\"TM\",\"city\":\"Ashgabat\",\"cuts\":[{\"slug\":\"ashgabat-centre\",\"signature\":true}],\"lesson\":\"Ashgabat was rebuilt after a 1948 earthquake and again after 1991 in white marble, holding the world record for marble-clad buildings.\"},{\"country\":\"BT\",\"city\":\"Thimphu\",\"cuts\":[{\"slug\":\"thimphu-centre\",\"signature\":true}],\"lesson\":\"Thimphu runs along a single valley floor and is famously the only capital with no traffic lights, policemen directing cars instead.\"}]")
